callGraph.callee:
voices
                    .into_iter()
                    .map(|v| Voice2 {
                        beats: v.beats.into_iter().map(beat).collect(),
                        ext: Vec::new(),
                    }).collect

Score2::from_v1(Score {
                master_bars: vec![oxiguitar_host::api::score::MasterBar {
                    time_signature: oxiguitar_host::api::score::TimeSignature {
                        numerator: 4,
                        denominator: 4,
                    },
                    key_signature: oxiguitar_host::api::score::KeySignature {
                        fifths: 0,
                        mode: oxiguitar_host::api::score::KeyMode::Major,
                    },
                    repeat_start: false,
                    repeat_end: None,
                    alternate_endings: 0,
                    marker: None,
                    double_bar: false,
                    triplet_feel: oxiguitar_host::api::score::TripletFeel::None,
                    tempo_changes: vec![],
                    directions: vec![],
                }],
                ..Score::default()
            })
            .master_bars[0].clone

(0..tracks)
        .map(|i| PreparedTrack {
            info: TrackInfo {
                index: i as u32,
                name: score.tracks[i].name.clone(),
                class,
            },
            program: score.tracks[i].instrument.midi_program,
            percussion: false,
            tuning: Vec::new(),
            capo: 0,
            settings: "{}".into(),
        }).collect

plugins
        .prepare(
            instrument,
            Prepare {
                instrument: String::new(),
                rate: 48_000,
                frames: 512,
                tracks: prepared,
            },
        ).unwrap

catch_unwind(AssertUnwindSafe(|| {
            let mut piece = Piece::new(
                events,
                pitch,
                call.time,
                call.step,
                frames,
                &mut buffers[..n],
            );
            renderer.render(&mut piece);
        })).is_ok

score2::Score2::from_v1(score::Score {
            master_bars: vec![score::MasterBar {
                time_signature: score::TimeSignature {
                    numerator: 4,
                    denominator: 4,
                },
                key_signature: score::KeySignature {
                    fifths: 0,
                    mode: score::KeyMode::Major,
                },
                repeat_start: false,
                repeat_end: None,
                alternate_endings: 0,
                marker: None,
                double_bar: false,
                triplet_feel: score::TripletFeel::None,
                tempo_changes: vec![],
                directions: vec![],
            }],
            ..score::Score::default()
        })
        .master_bars.remove

run
        .glyphs
        .iter()
        .enumerate()
        .map(|(i, g)| {
            let start = g.cluster as usize;
            let end = run
                .glyphs
                .get(i + 1)
                .map_or(run.text.len(), |n| n.cluster as usize)
                .max(start);
            let glyph = KrillaGlyph::new(
                GlyphId::new(u32::from(g.id)),
                g.advance / size,
                (g.x - pen) / size,
                0.0,
                0.0,
                start..end,
                None,
            );
            pen += g.advance;
            glyph
        }).collect
